window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b913a670d213ad23"]={"versions": [{"id": "FIG-b913a670d213ad23", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) für die E2E-Kommunikationsabsicherung gemäß AUTOSAR E2E-Protokoll, Profile 5. Das Diagramm spezifiziert den isolierten Teilschritt „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P05Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Initialknoten: Startpunkt der Sequenz.\n</li><li>Aktionsknoten: <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code>.\n</li><li>Endknoten: Aktivitätsendknoten (Activity Final Node).\n</li><li>Kontextindikator: Oben links platziertes Element mit Bezeichner <code>E2E_P05Protect()</code> und Verschachtelungs-/Verknüpfungssymbol (Loop-Symbol).\n</li><li>Datenelemente und Parameter: Quellvariable <code>State-&gt;Counter</code> (1 Byte), Zielarray <code>Data</code> an Index <code>[Offset+2]</code>, Berechnungsbasis <code>Offset</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten bei Aufruf des Teilschritts „Write Counter“ innerhalb von <code>E2E_P05Protect()</code>.\n</li><li>Ausführung der Zuweisung: Der 1 Byte große Zählerstand aus dem Zustandskonstrukt (<code>State-&gt;Counter</code>) wird an die Byte-Position <code>Data[Offset+2]</code> im Nutzdatenpuffer in Little-Endian-Reihenfolge geschrieben.\n</li><li>Kontrollflussübergang auf den Aktivitätsendknoten und Beendigung dieses Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorschrift für Implementierungen von E2E Profile 5 (<code>[PRS_E2E_00405]</code>). Der Sequenzschritt erzwingt die exakte Platzierung des 1-Byte-Counters im Datenframe an Byte-Position <code>Offset + 2</code>. Entwickler müssen sicherstellen, dass das Zielarray <code>Data</code> an der berechneten Offset-Position adressierbar ist und der Zählerwert formatspezifisch (Little Endian) serialisiert wird.</p>"}, {"id": "FIG-13d92395c7f12536", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) für die E2E-Kommunikationsabsicherung gemäß AUTOSAR E2E-Protokoll, Profile 5. Das Diagramm spezifiziert den isolierten Teilschritt „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P05Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Initialknoten: Startpunkt der Sequenz.\n</li><li>Aktionsknoten: <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code>.\n</li><li>Endknoten: Aktivitätsendknoten (Activity Final Node).\n</li><li>Kontextindikator: Oben links platziertes Element mit Bezeichner <code>E2E_P05Protect()</code> und Verschachtelungs-/Verknüpfungssymbol (Loop-Symbol).\n</li><li>Datenelemente und Parameter: Quellvariable <code>State-&gt;Counter</code> (1 Byte), Zielarray <code>Data</code> an Index <code>[Offset+2]</code>, Berechnungsbasis <code>Offset</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten bei Aufruf des Teilschritts „Write Counter“ innerhalb von <code>E2E_P05Protect()</code>.\n</li><li>Ausführung der Zuweisung: Der 1 Byte große Zählerstand aus dem Zustandskonstrukt (<code>State-&gt;Counter</code>) wird an die Byte-Position <code>Data[Offset+2]</code> im Nutzdatenpuffer in Little-Endian-Reihenfolge geschrieben.\n</li><li>Kontrollflussübergang auf den Aktivitätsendknoten und Beendigung dieses Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorschrift für Implementierungen von E2E Profile 5 (<code>[PRS_E2E_00405]</code>). Der Sequenzschritt erzwingt die exakte Platzierung des 1-Byte-Counters im Datenframe an Byte-Position <code>Offset + 2</code>. Entwickler müssen sicherstellen, dass das Zielarray <code>Data</code> an der berechneten Offset-Position adressierbar ist und der Zählerwert formatspezifisch (Little Endian) serialisiert wird.</p>"}, {"id": "FIG-bf79e2e72a59e451", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) für die E2E-Kommunikationsabsicherung gemäß AUTOSAR E2E-Protokoll, Profile 5. Das Diagramm spezifiziert den isolierten Teilschritt „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P05Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Initialknoten: Startpunkt der Sequenz.\n</li><li>Aktionsknoten: <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code>.\n</li><li>Endknoten: Aktivitätsendknoten (Activity Final Node).\n</li><li>Kontextindikator: Oben links platziertes Element mit Bezeichner <code>E2E_P05Protect()</code> und Verschachtelungs-/Verknüpfungssymbol (Loop-Symbol).\n</li><li>Datenelemente und Parameter: Quellvariable <code>State-&gt;Counter</code> (1 Byte), Zielarray <code>Data</code> an Index <code>[Offset+2]</code>, Berechnungsbasis <code>Offset</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten bei Aufruf des Teilschritts „Write Counter“ innerhalb von <code>E2E_P05Protect()</code>.\n</li><li>Ausführung der Zuweisung: Der 1 Byte große Zählerstand aus dem Zustandskonstrukt (<code>State-&gt;Counter</code>) wird an die Byte-Position <code>Data[Offset+2]</code> im Nutzdatenpuffer in Little-Endian-Reihenfolge geschrieben.\n</li><li>Kontrollflussübergang auf den Aktivitätsendknoten und Beendigung dieses Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorschrift für Implementierungen von E2E Profile 5 (<code>[PRS_E2E_00405]</code>). Der Sequenzschritt erzwingt die exakte Platzierung des 1-Byte-Counters im Datenframe an Byte-Position <code>Offset + 2</code>. Entwickler müssen sicherstellen, dass das Zielarray <code>Data</code> an der berechneten Offset-Position adressierbar ist und der Zählerwert formatspezifisch (Little Endian) serialisiert wird.</p>"}], "trans": [{"from": "FIG-b913a670d213ad23", "to": "FIG-13d92395c7f12536", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-13d92395c7f12536", "to": "FIG-bf79e2e72a59e451", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
